#include <iostream>
#include <vector>
#include <string>
using namespace std;

class Wallet;

class Auditor {
private:
    int checks;
public:
    Auditor() : checks(0) {}
    int getChecks() const { return checks; }
    bool inspect(const Wallet& w);
    friend int transfer(Wallet& from, Wallet& to, int amount);
    friend void audit(const Wallet& w, Auditor& a);
};

class Wallet {
    friend class Auditor;
private:
    string owner;
    int balance;
public:
    Wallet(string o, int b) : owner(o), balance(b) {}
    int getBalance() const { return balance; }
    string getOwner() const { return owner; }
    friend int transfer(Wallet& from, Wallet& to, int amount);
    friend void audit(const Wallet& w, Auditor& a);
};

bool Auditor::inspect(const Wallet& w) {
    checks++;
    return w.balance >= 0 && !w.owner.empty();
}

int transfer(Wallet& from, Wallet& to, int amount) {
    if (from.balance < amount) return 0;
    from.balance -= amount;
    to.balance += amount;
    return amount;
}

void audit(const Wallet& w, Auditor& a) {
    a.checks += (w.balance > 100) ? 2 : 1;
}

int main() {
    vector<Wallet> ws;
    ws.push_back(Wallet("Amy", 150));
    ws.push_back(Wallet("Bob", 20));
    ws.push_back(Wallet("Cy", 0));
    Auditor au;
    int moved = 0;
    moved += transfer(ws[0], ws[1], 60);
    moved += transfer(ws[1], ws[2], 500);
    moved += transfer(ws[1], ws[2], 70);
    for (size_t i = 0; i < ws.size(); i++) {
        audit(ws[i], au);
        cout << ws[i].getOwner() << " " << ws[i].getBalance() << " " << au.inspect(ws[i]) << endl;
    }
    cout << "moved=" << moved << " checks=" << au.getChecks() << endl;
    return 0;
}

#include <iostream>
#include <vector>
using namespace std;

class Vec2 {
private:
    friend Vec2 add(Vec2 a, const Vec2& b);
    friend Vec2& scale(Vec2& v, int k);
    friend Vec2* farthest(vector<Vec2>& vs);
    int x, y;
    int norm2() const { return x * x + y * y; }
public:
    Vec2() : x(0), y(0) {}
    Vec2(int a, int b) : x(a), y(b) {}
    int getX() const { return x; }
    int getY() const { return y; }
    friend ostream& operator<<(ostream& os, const Vec2& v);
};

Vec2 add(Vec2 a, const Vec2& b) {
    a.x += b.x;
    a.y += b.y;
    return a;
}

Vec2& scale(Vec2& v, int k) {
    v.x *= k;
    v.y *= k;
    return v;
}

Vec2* farthest(vector<Vec2>& vs) {
    if (vs.empty()) return nullptr;
    Vec2* best = &vs[0];
    for (size_t i = 1; i < vs.size(); i++) {
        if (vs[i].norm2() > best->norm2()) best = &vs[i];
    }
    return best;
}

ostream& operator<<(ostream& os, const Vec2& v) {
    os << "(" << v.x << ", " << v.y << ")";
    return os;
}

int main() {
    vector<Vec2> vs;
    vs.push_back(Vec2(1, 2));
    vs.push_back(Vec2(-3, 4));
    vs.push_back(Vec2(2, 2));
    Vec2 s = add(vs[0], vs[2]);
    cout << s << endl;
    scale(scale(vs[0], 3), 2);
    cout << vs[0] << endl;
    Vec2* f = farthest(vs);
    cout << *f << " " << f->getX() << endl;
    vector<Vec2> empty;
    cout << (farthest(empty) == nullptr) << endl;
    return 0;
}

#include <iostream>
#include <string>
#include <vector>
using namespace std;

class Book;

class Member {
    string name;
    int borrowed;
public:
    Member(const string& n) : name(n), borrowed(0) {}
    bool borrow(Book& b);
    void report() const { cout << name << " has " << borrowed << endl; }
};

class Book {
    friend bool Member::borrow(Book& b);
private:
    string title;
    bool out;
public:
    Book(const string& t) : title(t), out(false) {}
    const string& getTitle() const { return title; }
    bool isOut() const { return out; }
};

bool Member::borrow(Book& b) {
    if (b.out) return false;
    b.out = true;
    borrowed++;
    return true;
}

class Library {
private:
    vector<Book> books;
    int lent;
public:
    Library() : lent(0) {}
    void add(const Book& b) { books.push_back(b); }
    friend int countLent(const Library& l) {
        int c = 0;
        for (size_t i = 0; i < l.books.size(); i++)
            if (l.books[i].isOut()) c++;
        return c;
    }
    Book& at(int i) { return books[i]; }
};

int main() {
    Library lib;
    lib.add(Book("Algorithms"));
    lib.add(Book("Compilers"));
    lib.add(Book("Networks"));
    Member m("Dana");
    for (int i = 0; i < 3; i++) {
        bool ok = m.borrow(lib.at(i % 2));
        cout << lib.at(i % 2).getTitle() << " " << ok << endl;
    }
    m.report();
    cout << countLent(lib) << endl;
    return 0;
}

#include <iostream>
#include <vector>
using namespace std;

class Matrix;

namespace util {
    int trace(const Matrix& m);
}

class Matrix {
private:
    int n;
    vector<vector<int> > a;
public:
    Matrix(int size) : n(size), a(size, vector<int>(size, 0)) {}
    friend class MatrixOps;
    void set(int i, int j, int v) { a[i][j] = v; }
    friend int util::trace(const Matrix& m);
    int size() const { return n; }
};

class MatrixOps {
public:
    static void transpose(Matrix& m) {
        for (int i = 0; i < m.n; i++)
            for (int j = i + 1; j < m.n; j++) {
                int t = m.a[i][j];
                m.a[i][j] = m.a[j][i];
                m.a[j][i] = t;
            }
    }
    Matrix multiply(const Matrix& x, const Matrix& y) {
        Matrix r(x.n);
        for (int i = 0; i < x.n; i++)
            for (int j = 0; j < x.n; j++)
                for (int k = 0; k < x.n; k++)
                    r.a[i][j] += x.a[i][k] * y.a[k][j];
        return r;
    }
    void print(const Matrix& m) {
        for (int i = 0; i < m.n; i++) {
            for (int j = 0; j < m.n; j++) cout << m.a[i][j] << " ";
            cout << "\n";
        }
    }
};

int util::trace(const Matrix& m) {
    int t = 0;
    for (int i = 0; i < m.n; i++) t += m.a[i][i];
    return t;
}

int main() {
    Matrix p(3), q(3);
    int c = 1;
    for (int i = 0; i < 3; i++)
        for (int j = 0; j < 3; j++) {
            p.set(i, j, c);
            q.set(i, j, (i == j) ? 2 : 0);
            c++;
        }
    MatrixOps ops;
    Matrix r = ops.multiply(p, q);
    MatrixOps::transpose(r);
    ops.print(r);
    cout << util::trace(r) << endl;
    return 0;
}
